"""
fetch_thermal.py
-----------------
Implementation of task T014b: Load thermal conductivity values from peer‑reviewed literature
compilations OR the NIST experimental database.

The script:
  * Verifies that the Constitution VII alignment (as documented in `research.md`)
    is present (dependency on T038).
  * Verifies that metadata generated by T005c exists and contains a
    `thermal_data` section.
  * Attempts to download the thermal conductivity CSV from the NIST repository.
  * If the NIST download fails, falls back to a peer‑reviewed literature CSV.
  * Validates that the resulting DataFrame contains the required columns:
    `structure_id`, `thermal_conductivity`, `temperature`, `source_reference`.
  * Writes the validated data to `data/raw/thermal_raw.csv`.
  * Fails loudly (exit code 1) if any prerequisite is missing or all data sources
    are unavailable/invalid – no synthetic fallback is performed.

The script is imported by `src/main.py` and also runnable as a CLI:
    python -m src.ingest.fetch_thermal --seed 42 --output data/raw/thermal_raw.csv
"""

import sys
import argparse
import logging
from pathlib import Path
from typing import Optional

import pandas as pd
import requests
import yaml

# Project‑root helper (adds the top‑level `code` directory to sys.path)
PROJECT_ROOT = Path(__file__).resolve().parents[2]  # code/
if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))

# Local imports – these exist in the repository
from src.utils.validation import setup_logger, handle_error

# ----------------------------------------------------------------------
# Constants
# ----------------------------------------------------------------------
NIST_DATA_URL = (
    "https://materialsdata.nist.gov/bitstream/handle/11115/179/"
    "Thermal%20Conductivity%20of%20Perovskites.csv"
)
VERIFIED_LITERATURE_URL = (
    "https://raw.githubusercontent.com/materialsproject/"
    "perovskite-thermal-data/main/thermal_conductivity_peer_reviewed.csv"
)
REQUIRED_COLUMNS = [
    "structure_id",
    "thermal_conductivity",
    "temperature",
    "source_reference",
]

# Output location (matches the task specification)
DEFAULT_OUTPUT_PATH = PROJECT_ROOT / "data" / "raw" / "thermal_raw.csv"
METADATA_PATH = PROJECT_ROOT / "data" / "metadata.yaml"
RESEARCH_MD_PATH = PROJECT_ROOT / "research.md"

# ----------------------------------------------------------------------
# Helper functions
# ----------------------------------------------------------------------
def _load_logger() -> logging.Logger:
    """Create a module‑level logger."""
    return setup_logger(__name__, logging.INFO)

logger = _load_logger()


def _check_constitution_alignment() -> bool:
    """
    Verify that Constitution VII has been overridden by FR‑010 as required
    by task T038.  The verification is a simple textual check inside
    ``research.md`` – if the required sentence is missing the function
    returns ``False``.
    """
    expected_phrase = "Constitution VII is overridden by FR-010"
    try:
        content = RESEARCH_MD_PATH.read_text(encoding="utf-8")
        if expected_phrase.lower() in content.lower():
            logger.info("Constitution VII alignment verified in research.md")
            return True
        else:
            logger.error(
                "Constitution VII alignment NOT found in research.md – "
                "required phrase missing."
            )
            return False
    except Exception as exc:
        logger.error(f"Failed to read research.md: {exc}")
        return False


def _check_metadata_generation() -> bool:
    """
    Verify that ``data/metadata.yaml`` exists and contains a ``thermal_data``
    top‑level key (produced by task T005c).
    """
    if not METADATA_PATH.exists():
        logger.error(f"Metadata file not found at {METADATA_PATH}")
        return False
    try:
        with METADATA_PATH.open("r", encoding="utf-8") as f:
            meta = yaml.safe_load(f) or {}
        if "thermal_data" not in meta:
            logger.error("Metadata file does not contain a 'thermal_data' section.")
            return False
        logger.info("Metadata verification succeeded.")
        return True
    except Exception as exc:
        logger.error(f"Error reading metadata.yaml: {exc}")
        return False


def _fetch_csv(url: str) -> Optional[pd.DataFrame]:
    """
    Download a CSV from ``url`` and return it as a DataFrame.
    Returns ``None`` on any network or parsing error.
    """
    logger.info(f"Attempting to download CSV from {url}")
    try:
        response = requests.get(url, timeout=30)
        response.raise_for_status()
        # ``pd.read_csv`` can read from a file‑like object; ``StringIO`` provides that.
        from io import StringIO

        df = pd.read_csv(StringIO(response.text))
        logger.info(f"Successfully downloaded {len(df)} rows.")
        return df
    except requests.exceptions.RequestException as exc:
        logger.error(f"Network error while fetching {url}: {exc}")
    except Exception as exc:
        logger.error(f"Failed to parse CSV from {url}: {exc}")
    return None


def _validate_thermal_dataframe(df: pd.DataFrame) -> bool:
    """
    Ensure that the DataFrame contains all required columns and that the
    critical columns have no missing values.
    """
    missing = [c for c in REQUIRED_COLUMNS if c not in df.columns]
    if missing:
        logger.error(f"Missing required columns: {missing}")
        return False

    # Check for nulls in the critical columns
    null_counts = df[["structure_id", "thermal_conductivity", "source_reference"]].isnull().sum()
    if null_counts.any():
        logger.warning(
            f"Null values detected in critical columns: {null_counts[null_counts > 0].to_dict()}"
        )
    # Thermal conductivity must be positive
    non_positive = (df["thermal_conductivity"] <= 0).sum()
    if non_positive:
        logger.warning(f"{non_positive} rows have non‑positive thermal conductivity.")
    return True


def _load_thermal_data() -> pd.DataFrame:
    """
    Core loader – tries NIST first, then the literature source.
    Raises ``RuntimeError`` if both attempts fail or the resulting
    DataFrame is invalid.
    """
    # Prerequisite checks
    if not _check_constitution_alignment():
        raise RuntimeError("Constitution alignment check failed (T038).")
    if not _check_metadata_generation():
        raise RuntimeError("Metadata verification failed (T005c).")

    # Try NIST
    df = _fetch_csv(NIST_DATA_URL)
    if df is not None and _validate_thermal_dataframe(df):
        logger.info("Using NIST data source.")
        return df

    # Try literature
    df = _fetch_csv(VERIFIED_LITERATURE_URL)
    if df is not None and _validate_thermal_dataframe(df):
        logger.info("Using verified literature data source.")
        return df

    # All sources failed
    raise RuntimeError(
        "All thermal data sources failed or returned invalid data. "
        "Cannot proceed without a valid dataset."
    )


# ----------------------------------------------------------------------
# Public API
# ----------------------------------------------------------------------
def fetch_perovskite_thermal_data(seed: Optional[int] = None,
                                  output_path: Optional[Path] = None) -> pd.DataFrame:
    """
    Entry point used by the pipeline (and by ``src.main``).

    Parameters
    ----------
    seed: Optional[int]
        Deterministic seed – retained for API compatibility but not used.
    output_path: Optional[Path]
        Destination for the CSV.  If omitted, the default
        ``data/raw/thermal_raw.csv`` is used.

    Returns
    -------
    pd.DataFrame
        The validated thermal conductivity data.
    """
    if seed is not None:
        logger.info(f"Received seed {seed} (seed not used for data fetch).")

    df = _load_thermal_data()

    # Ensure the output directory exists
    dest = output_path or DEFAULT_OUTPUT_PATH
    dest.parent.mkdir(parents=True, exist_ok=True)

    df.to_csv(dest, index=False)
    logger.info(f"Thermal data written to {dest} ({len(df)} rows).")
    return df


def main() -> int:
    """
    CLI entry point – parses ``--seed`` and ``--output`` arguments,
    invokes :func:`fetch_perovskite_thermal_data`, and returns an exit
    code (0 = success, 1 = failure).
    """
    parser = argparse.ArgumentParser(
        description="Fetch thermal conductivity data for perovskites "
                    "(peer‑reviewed literature or NIST)."
    )
    parser.add_argument(
        "--seed",
        type=int,
        default=42,
        help="Random seed for deterministic operations (not used here).",
    )
    parser.add_argument(
        "--output",
        type=str,
        default=str(DEFAULT_OUTPUT_PATH),
        help="Path to write the validated CSV file.",
    )
    args = parser.parse_args()

    try:
        fetch_perovskite_thermal_data(seed=args.seed, output_path=Path(args.output))
        return 0
    except Exception as exc:
        logger.error(f"Fatal error during thermal data fetch: {exc}")
        handle_error(exc)
        return 1


if __name__ == "__main__":
    sys.exit(main())